<template><div class="page"><div class="page-header"><h2>SLA 监控</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="maintenance_id" label="工单号" width="120"/><el-table-column prop="sla_id" label="SLA编号" width="100"/><el-table-column label="SLA状态" width="80"><template #default="{row}"><el-tag :type="slaStatusTag(row.sla_status)" size="small">{{ slaStatusLabel(row.sla_status) }}</el-tag></template></el-table-column><el-table-column label="响应达标" width="80"><template #default="{row}"><el-tag :type="row.response_met?'success':'danger'" size="small">{{ row.response_met?'是':'否' }}</el-tag></template></el-table-column><el-table-column label="解决达标" width="80"><template #default="{row}"><el-tag :type="row.resolve_met?'success':'danger'" size="small">{{ row.resolve_met?'是':'否' }}</el-tag></template></el-table-column><el-table-column prop="response_elapsed_minutes" label="响应耗时(分)" width="110"/><el-table-column prop="resolve_elapsed_minutes" label="解决耗时(分)" width="110"/><el-table-column prop="created_time" label="工单创建" width="110"/></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'SLA工单 — '+(detail?.maintenance_id||'')" v-model="drawer" width="550px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="工单号">{{ detail.maintenance_id }}</el-descriptions-item><el-descriptions-item label="SLA编号">{{ detail.sla_id }}</el-descriptions-item><el-descriptions-item label="SLA状态"><el-tag :type="slaStatusTag(detail.sla_status)" size="small">{{ slaStatusLabel(detail.sla_status) }}</el-tag></el-descriptions-item><el-descriptions-item label="是否升级">{{ detail.escalated?'是':'否' }}</el-descriptions-item><el-descriptions-item label="响应达标">{{ detail.response_met?'是':'否' }}</el-descriptions-item><el-descriptions-item label="解决达标">{{ detail.resolve_met?'是':'否' }}</el-descriptions-item><el-descriptions-item label="响应耗时">{{ detail.response_elapsed_minutes||'-' }}分钟</el-descriptions-item><el-descriptions-item label="解决耗时">{{ detail.resolve_elapsed_minutes||'-' }}分钟</el-descriptions-item><el-descriptions-item label="工单创建">{{ detail.created_time||'-' }}</el-descriptions-item><el-descriptions-item label="首次响应">{{ detail.first_response_time||'-' }}</el-descriptions-item><el-descriptions-item label="解决时间">{{ detail.resolved_time||'-' }}</el-descriptions-item></el-descriptions></template></el-dialog></div></template>
<script setup lang="ts">import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {fetchSlaTickets} from '@/api/sla';import type {SlaRecord} from '@/api/sla'
const{items,loading,page,perPage,total}=useListPage<SlaRecord>(fetchSlaTickets);const{drawer,detail,open}=useDetailDrawer<SlaRecord>()
function slaStatusTag(s:string){const m:Record<string,string>={'00':'success','01':'warning','02':'danger','99':'info'};return m[s]||'info'}
function slaStatusLabel(s:string){const m:Record<string,string>={'00':'正常','01':'预警','02':'违约','99':'关闭'};return m[s]||s}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}</style>
